def transform_v3(grid):
    """
    Transformation: Pattern propagates from rightmost region to left regions.
    For each row, copy the pattern from IN[src_row]'s right region to all regions.
    """
    H, W = len(grid), len(grid[0])
    cross_row = 7
    cross_cols = [6, 13]

    # Right region is non-cross area at right
    right_region = (14, 19)  # 6 values
    left_region = (7, 12)    # 6 values

    # Build source map: for each output row, which input row provides the pattern
    src_map = {}
    for r in range(H):
        if r == cross_row:
            src_map[r] = cross_row  # Keep cross row
        elif r < cross_row:
            # OUT[0] from IN[8], OUT[1] from IN[9], etc.
            src_map[r] = 8 + r
        else:
            # Row >= 8: src[r] = r, but wrap if r > 13
            src_map[r] = r
            if src_map[r] > 13:
                src_map[r] = 8 + (src_map[r] - 8) % 7

    print("Source map:", src_map)

    result = [[0]*W for _ in range(H)]

    # Copy cross structure
    # Cross row (all 4s)
    for c in range(W):
        result[cross_row][c] = 4

    # Cross columns (all 4s)
    for c in cross_cols:
        for r in range(H):
            result[r][c] = 4

    # Fill patterns for each row
    for r in range(H):
        if r == cross_row:
            continue

        src_r = src_map[r]
        pattern = tuple(grid[src_r][c] for c in range(right_region[0], right_region[1] + 1))

        # Fill left region (cols 7-12)
        for c in range(left_region[0], left_region[1] + 1):
            result[r][c] = pattern[c - left_region[0]]

        # Fill right region (cols 14-19)
        for c in range(right_region[0], right_region[1] + 1):
            result[r][c] = pattern[c - right_region[0]]

        # Row 6 is special - it has the pattern from IN[14] which is uniform (all 8s)

    return result

