def transform_demo(grid):
    H, W = len(grid), len(grid[0])
    cross_row = 7
    cross_cols = [6, 13]
    regions = [(0, 5), (7, 12), (14, 19)]

    def get_src_row(r):
        if r == cross_row:
            return cross_row
        if r < cross_row:
            return 8 + r  # OUT[0] from IN[8], etc.
        return r

    result = [[0]*W for _ in range(H)]

    for c in range(W):
        result[cross_row][c] = 4

    for r in range(H):
        for c in cross_cols:
            result[r][c] = 4

    for r in range(H):
        if r == cross_row:
            continue

        src_r = get_src_row(r)
        pattern = tuple(grid[src_r][c] for c in range(14, 20))

        for c_start, c_end in regions:
            for c in range(c_start, c_end + 1):
                local_idx = c - c_start
                if local_idx < len(pattern):
                    result[r][c] = pattern[local_idx]
                else:
                    result[r][c] = pattern[-1]

    return result

